const long long MOD = 1000000007LL;

struct Matrix {
    int n;
    vector<vector<long long>> a;
    Matrix() : n(0) {}
    Matrix(int n_) : n(n_), a(n_, vector<long long>(n_, 0)) {}
    static Matrix identity(int n) {
        Matrix I(n);
        for (int i = 0; i < n; ++i) I.a[i][i] = 1;
        return I;
    }
    Matrix operator*(const Matrix &b) const {
        int N = n;
        Matrix res(N);
        for (int i = 0; i < N; ++i) {
            for (int k = 0; k < N; ++k) {
                if (a[i][k] == 0) continue;
                long long v = a[i][k];
                for (int j = 0; j < N; ++j) {
                    if (b.a[k][j] == 0) continue;
                    res.a[i][j] = (res.a[i][j] + v * b.a[k][j]) % MOD;
                }
            }
        }
        return res;
    }
};

Matrix mat_pow(Matrix base, long long exp) {
    Matrix res = Matrix::identity(base.n);
    while (exp > 0) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long m, k;
    cin >> n >> m >> k;
    Matrix A(n);
    for (long long i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        A.a[u][v] = (A.a[u][v] + 1) % MOD;
    }

    if (k == 0) {
        cout << ( (0 == n-1) ? 1 : 0 ) << '\n';
        return 0;
    }

    Matrix B = mat_pow(A, k);
    cout << B.a[0][n-1] % MOD << '\n';
}
